const data = $input.first().json;

if (!data.email && !data.phone) {
  throw new Error('Lead missing both email and phone — cannot process');
}

const leadId = 'LEAD-' + Date.now() + '-' + Math.random().toString(36).substr(2, 9).toUpperCase();

const lead = {
  leadId,
  firstName:      (data.firstName || '').trim(),
  lastName:       (data.lastName || '').trim(),
  fullName:       (data.fullName || ((data.firstName || '') + ' ' + (data.lastName || '')).trim()),
  phone:          (data.phone || '').replace(/[^0-9+\-()\s]/g, ''),
  email:          (data.email || '').toLowerCase().trim(),
  caseType:       (data.caseType || '').trim(),
  description:    (data.description || '').trim().substring(0, 4000),
  jurisdiction:   (data.jurisdiction || '').trim(),
  urgency:        data.urgency || 'normal',
  source:         data.source || 'unknown',
  adverseParties: (data.adverseParties || '').trim(),
  referredBy:     (data.referredBy || '').trim(),
  callId:         data.callId || '',
  intakeTimestamp:data.intakeTimestamp || new Date().toISOString()
};

const systemPrompt = `You are an intake qualification AI for a law firm. Your ONLY role is to evaluate whether a potential client meets the criteria for the firm to schedule a consultation.

CRITICAL GUARDRAILS:
- You do NOT provide legal advice, case evaluations, or predictions of legal outcomes
- You do NOT assess the merits or likely success of any case
- You only determine whether the inquiry fits the firm's practice areas and intake criteria

PRACTICE AREAS SERVED: Personal Injury, Family Law, Business Litigation, Estate Planning, Employment Law, Criminal Defense, Real Estate Law, Immigration

EVALUATION CRITERIA:
1. Practice area match — does the matter fall within a served area?
2. Jurisdiction — is the matter in a served state/jurisdiction? (flag if unclear)
3. Case cognizability — is this a genuine legal matter vs. a general question or hypothetical?
4. Statute of limitations urgency — any indicators of imminent deadlines?
5. Information completeness — enough detail to warrant scheduling a consultation?

Respond ONLY with a valid JSON object. No prose outside the JSON.

{
  "score": <integer 0-100>,
  "practiceAreaMatch": <boolean>,
  "jurisdictionMatch": <boolean>,
  "recommendConsultation": <boolean>,
  "urgencyLevel": "low" | "normal" | "high" | "urgent",
  "practiceAreaDetected": "<string>",
  "disqualificationReason": "<string or empty>",
  "followUpQuestions": ["<question1>", "<question2>"],
  "confidentialityNotice": "This communication is for intake screening only. No attorney-client relationship is established until a signed engagement agreement is in place."
}`;

return [{
  json: {
    lead,
    qualificationRequest: {
      model: 'claude-sonnet-5-5',
      max_tokens: 1024,
      system: systemPrompt,
      messages: [{
        role: 'user',
        content: `Qualify this intake lead:\n\nName: ${lead.fullName}\nCase Type: ${lead.caseType || 'Not specified'}\nJurisdiction: ${lead.jurisdiction || 'Not specified'}\nUrgency: ${lead.urgency}\nSource: ${lead.source}\nDescription: ${lead.description || 'None provided'}\nAdverse Parties: ${lead.adverseParties || 'None specified'}\nContact: ${lead.email || 'No email'} | ${lead.phone || 'No phone'}`
      }]
    }
  }
}];

const lead = $('Validate & Build AI Request').first().json.lead;
const aiResponse = $input.first().json;

let q;
try {
  const text = aiResponse.content?.[0]?.text || '{}';
  const match = text.match(/\{[\s\S]*\}/);
  q = JSON.parse(match ? match[0] : text);
} catch(e) {
  q = {
    score: 50,
    practiceAreaMatch: false,
    jurisdictionMatch: false,
    recommendConsultation: false,
    urgencyLevel: 'normal',
    practiceAreaDetected: lead.caseType || 'unknown',
    disqualificationReason: '',
    followUpQuestions: [],
    confidentialityNotice: 'This communication is for intake screening only. No attorney-client relationship is established until a signed engagement agreement is in place.'
  };
}

return [{
  json: {
    ...lead,
    qualification: {
      score:                  q.score ?? 50,
      practiceAreaMatch:      q.practiceAreaMatch ?? false,
      jurisdictionMatch:      q.jurisdictionMatch ?? false,
      recommendConsultation:  q.recommendConsultation ?? false,
      urgencyLevel:           q.urgencyLevel ?? 'normal',
      practiceAreaDetected:   q.practiceAreaDetected || lead.caseType || 'General',
      disqualificationReason: q.disqualificationReason || '',
      followUpQuestions:      q.followUpQuestions || [],
      confidentialityNotice:  q.confidentialityNotice || 'This communication is for intake screening only. No attorney-client relationship is established until a signed engagement agreement is in place.'
    },
    qualifiedAt: new Date().toISOString()
  }
}];

