parameters.jsCode:
const qualifiedLead = $('Parse Qualification Score').first().json;
const clioContacts = $input.first().json.data || [];

function jaro(a, b) {
  if (!a || !b) return 0;
  a = a.toLowerCase().trim(); b = b.toLowerCase().trim();
  if (a === b) return 1;
  const range = Math.floor(Math.max(a.length, b.length) / 2) - 1;
  const aMatch = new Array(a.length).fill(false);
  const bMatch = new Array(b.length).fill(false);
  let matches = 0, transpositions = 0;
  for (let i = 0; i < a.length; i++) {
    const lo = Math.max(0, i - range);
    const hi = Math.min(i + range + 1, b.length);
    for (let j = lo; j < hi; j++) {
      if (bMatch[j] || a[i] !== b[j]) continue;
      aMatch[i] = bMatch[j] = true; matches++; break;
    }
  }
  if (!matches) return 0;
  let k = 0;
  for (let i = 0; i < a.length; i++) {
    if (!aMatch[i]) continue;
    while (!bMatch[k]) k++;
    if (a[i] !== b[k++]) transpositions++;
  }
  return (matches / a.length + matches / b.length + (matches - transpositions / 2) / matches) / 3;
}

const newClientName = qualifiedLead.fullName || '';
const adverseNames = (qualifiedLead.adverseParties || '').split(',').map(s => s.trim()).filter(Boolean);
const conflicts = [];

for (const contact of clioContacts) {
  const cName = contact.name || '';
  const clientSim = jaro(newClientName, cName);
  if (clientSim >= 0.88) {
    conflicts.push({
      type: 'prospective_client_matches_existing_contact',
      prospectiveName: newClientName,
      existingName: cName,
      similarity: Math.round(clientSim * 100),
      clioContactId: contact.id,
      contactType: contact.type
    });
  }
  for (const adverse of adverseNames) {
    const advSim = jaro(adverse, cName);
    if (advSim >= 0.88) {
      conflicts.push({
        type: 'adverse_party_matches_existing_client',
        adversePartyName: adverse,
        existingName: cName,
        similarity: Math.round(advSim * 100),
        clioContactId: contact.id,
        contactType: contact.type
      });
    }
  }
}

return [{
  json: {
    ...qualifiedLead,
    conflictCheck: {
      performedAt:           new Date().toISOString(),
      totalContactsChecked:  clioContacts.length,
      conflicts,
      hasConflicts:          conflicts.length > 0,
      status:                conflicts.length > 0 ? 'CONFLICT_FLAGGED' : 'CLEAR',
      requiresAttorneyReview: conflicts.length > 0
    }
  }
}];

