={{ JSON.stringify({
  name: 'Engagement Letter — ' + $json.fullName + ' — ' + new Date().toLocaleDateString('en-US'),
  template_uuid: $vars['PANDADOC_TEMPLATE_' + ($json.qualification.practiceAreaDetected || 'GENERAL').toUpperCase().replace(/ /g, '_')] || $vars.PANDADOC_DEFAULT_TEMPLATE,
  recipients: [
    {
      email:      $json.email,
      first_name: $json.firstName,
      last_name:  $json.lastName,
      role:       'Client'
    }
  ],
  fields: {
    client_name:       { value: $json.fullName },
    client_email:      { value: $json.email },
    client_phone:      { value: $json.phone },
    practice_area:     { value: $json.qualification.practiceAreaDetected },
    matter_description:{ value: $json.caseType || $json.qualification.practiceAreaDetected },
    engagement_date:   { value: new Date().toLocaleDateString('en-US', { year: 'numeric', month: 'long', day: 'numeric' }) },
    firm_name:         { value: $vars.FIRM_NAME || 'Law Firm' },
    lead_id:           { value: $json.leadId }
  },
  metadata: {
    leadId:       $json.leadId,
    source:       $json.source,
    practiceArea: $json.qualification.practiceAreaDetected,
    intakeDate:   $json.intakeTimestamp
  },
  tags: ['intake-automation', $json.source, $json.qualification.practiceAreaDetected]
}) }}

